    def test_darkarts_fallback_minions_combined_and_terminal(self):
        cases=[('forest',4,6,8,[99921,99842,99758,99474,99190,98900,98610,98339]),
               ('dragon',6,9,20,[99901,99802,99697,99377,99057,98767,98477,98206])]
