            outcome=decode(f['snapshot']()[0]['badguy']); self.assertEqual({'dragonVictory':True,'dragonkills':0}, {k:v for k,v in outcome.items() if k!='dragonEncounter'}); self.assertRegex(outcome['dragonEncounter'],r'^[a-f0-9]{32}$')
