                f['patch'](f['player'],badguy=f['encode'](state),bufflist=f['encode'](buffs)); before=f['pvp_snapshot'](); data=f['pvp_form'](); code,body=f['request']('pvp.php?op=fight',data); self.assertEqual(200,code,body[:3000]); after=f['pvp_snapshot']()
